int process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_ticket *ticket = NULL;
    struct ceph_auth_handler *handler = NULL;
    void *ticket_data = NULL;
    size_t ticket_len = 0;
    struct ceph_crypto_key new_key;
    struct ceph_timespec ts;

    // Decode ticket type and version
    if (*p >= end) {
        goto out;
    }

    handler = get_ticket_handler(ac, *(int32_t *)*p);
    if (!handler) {
        goto out;
    }

    *p += sizeof(int32_t);

    if (*p >= end) {
        goto out;
    }

    ticket_len = le32_to_cpu(*(uint32_t *)*p);
    *p += sizeof(uint32_t);

    if (*p + ticket_len > end) {
        goto out;
    }

    ticket_data = *p;
    *p += ticket_len;

    // Allocate and decode ticket
    ticket = decode_ticket(ticket_data, ticket_len);
    if (!ticket) {
        goto out;
    }

    // Decrypt ticket data if necessary
    if (ticket->encrypted) {
        ret = decrypt_ticket(secret, ticket_data, ticket_len, &ticket_data, &ticket_len);
        if (ret < 0) {
            goto out;
        }
    }

    // Extract new session key and validity period
    if (ticket_data + sizeof(new_key) > *p) {
        ret = -EINVAL;
        goto out;
    }

    memcpy(&new_key, ticket_data, sizeof(new_key));
    ticket_data += sizeof(new_key);

    if (ticket_data + sizeof(ts) > *p) {
        ret = -EINVAL;
        goto out;
    }

    memcpy(&ts, ticket_data, sizeof(ts));
    ticket_data += sizeof(ts);

    // Update session key and ticket information
    ret = handler->update_key(ac, &new_key, &ts);
    if (ret < 0) {
        goto out;
    }

    ret = 0;

out:
    if (ticket) {
        free(ticket);
    }

    if (ticket_data && ticket != ticket_data) {
        free(ticket_data);
    }

    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end)
{
  int ret = -EINVAL;
  void *ticket_type, *struct_version;
  struct ceph_auth_ticket_handler *handler = NULL;
  struct ceph_crypto_key new_key = {0};
  void *validity, *ticket_blob;
  int encrypted = 0;

  if (!ac || !secret || !p || !*p || !end || *p > end) {
    goto out;
  }

  /* Decode ticket type and structure version */
  if (*p + sizeof(ticket_type) > end) {
    goto out;
  }
  ticket_type = *p;
  *p += sizeof(ticket_type);

  if (*p + sizeof(struct_version) > end) {
    goto out;
  }
  struct_version = *p;
  *p += sizeof(struct_version);

  /* Get the appropriate ticket handler */
  handler = ceph_get_ticket_handler(ticket_type, struct_version);
  if (!handler) {
    goto out;
  }

  if (handler->needs_decryption) {
    encrypted = 1;
    ret = ceph_decrypt_ticket(*p, end - *p, secret, &new_key, &validity, &ticket_blob);
    if (ret < 0) {
      goto out;
    }
  } else {
    if (*p + sizeof(validity) + sizeof(ticket_blob) > end) {
      goto out;
    }
    validity = *p;
    *p += sizeof(validity);
    ticket_blob = *p;
    *p += sizeof(ticket_blob);
  }

  /* Extract and process session key and ticket info */
  ret = handler->process_ticket(ac, &new_key, validity, ticket_blob);
  if (ret < 0) {
    goto out;
  }

  ret = 0;

out:
  if (handler) {
    ceph_put_ticket_handler(handler);
  }
  if (encrypted) {
    ceph_free_decrypted_data(&new_key, validity, ticket_blob);
  }
  return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket *ticket = NULL;
    struct ceph_auth_ticket_handler *handler = NULL;
    void *ticket_data = NULL;
    size_t ticket_len;
    struct ceph_crypto_key new_key;
    struct ceph_timespec expire;
    void *blob = NULL;
    size_t blob_len;

    // Decode the ticket type and structure version
    if (*p >= end) {
        goto out;
    }

    // Retrieve the appropriate ticket handler
    handler = ceph_get_ticket_handler(ac, (*p));
    if (!handler) {
        goto out;
    }

    // Parse ticket length and allocate memory
    ticket_len = ceph_decode_32((void **)p);
    if (*p + ticket_len > end) {
        goto out;
    }

    ticket_data = *p;
    *p += ticket_len;

    // Decrypt the ticket data if necessary
    if (handler->decrypt) {
        ret = handler->decrypt(secret, &ticket_data, &ticket_len);
        if (ret < 0) {
            goto out;
        }
    }

    // Parse session key and validity
    if (ticket_data + sizeof(new_key) > *p) {
        goto out;
    }

    memcpy(&new_key, ticket_data, sizeof(new_key));
    ticket_data += sizeof(new_key);

    if (ticket_data + sizeof(expire) > *p) {
        goto out;
    }

    memcpy(&expire, ticket_data, sizeof(expire));
    ticket_data += sizeof(expire);

    // Parse the ticket blob
    blob_len = ceph_decode_32((void **)&ticket_data);
    if (ticket_data + blob_len > *p) {
        goto out;
    }

    blob = ticket_data;
    ticket_data += blob_len;

    // Update session key and ticket information in the handler
    ret = handler->update_ticket(ac, &new_key, &expire, blob, blob_len);
    if (ret < 0) {
        goto out;
    }

    ret = 0;

out:
    // Clean up allocated resources
    if (blob && handler->decrypt) {
        free(blob);
    }

    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int err = 0;
    struct ceph_auth_ticket *ticket;
    void *ticket_data;
    size_t ticket_len;
    struct ceph_auth_ticket_handler *handler;

    // Decode ticket type and structure version
    if (ceph_decode_dout(p, end, &ticket_len) < 0)
        return -EINVAL;

    ticket = ceph_decode_flat_obj(p, end, &ticket_len);
    if (IS_ERR(ticket))
        return PTR_ERR(ticket);

    handler = get_ticket_handler(ac, ticket->type);
    if (!handler) {
        err = -ENOTSUPP;
        goto out;
    }

    // Decrypt ticket data if needed
    if (ticket->encrypted) {
        ticket_data = decrypt_ticket(secret, ticket->data, ticket_len);
        if (!ticket_data) {
            err = -EINVAL;
            goto out;
        }
    } else {
        ticket_data = ticket->data;
    }

    // Extract session key, validity period, and ticket blob
    struct ceph_crypto_key new_key;
    int64_t valid_from, valid_until;
    void *blob;
    size_t blob_len;

    if (parse_ticket_data(ticket_data, ticket_len, &new_key, &valid_from, &valid_until, &blob, &blob_len) < 0) {
        err = -EINVAL;
        goto out;
    }

    // Update session key and ticket information in the handler
    ceph_crypto_key_free(&ac->session_key);
    ac->session_key = new_key;
    ac->valid_from = valid_from;
    ac->valid_until = valid_until;

    handler->ticket_blob = blob;
    handler->ticket_blob_len = blob_len;

out:
    kfree(ticket);
    return err;
}

int process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = 0;
    void *ticket_start = *p;
    uint32_t ticket_type, version;

    // Decode ticket type and version
    if (*p + sizeof(ticket_type) > end) {
        return -EINVAL;
    }
    memcpy(&ticket_type, *p, sizeof(ticket_type));
    *p += sizeof(ticket_type);

    if (*p + sizeof(version) > end) {
        return -EINVAL;
    }
    memcpy(&version, *p, sizeof(version));
    *p += sizeof(version);

    // Retrieve the appropriate ticket handler
    struct ceph_auth_ticket_handler *handler = get_ticket_handler(ticket_type, version);
    if (!handler) {
        return -ENOTSUP;
    }

    // Decrypt ticket data
    void *encrypted_data = *p;
    size_t encrypted_len = (uintptr_t)end - (uintptr_t)*p;
    void *decrypted_data = NULL;
    size_t decrypted_len = 0;

    ret = decrypt_data(encrypted_data, encrypted_len, secret, &decrypted_data, &decrypted_len);
    if (ret < 0) {
        return ret;
    }

    // Extract new session key, validity period, and ticket blob
    struct ceph_crypto_key *new_key = extract_key(decrypted_data, decrypted_len);
    if (!new_key) {
        ret = -EINVAL;
        goto out;
    }

    uint64_t start, expiry;
    void *ticket_blob = extract_ticket_blob(decrypted_data, decrypted_len, &start, &expiry);
    if (!ticket_blob) {
        ret = -EINVAL;
        goto out;
    }

    // Update the session key and ticket information in the handler
    ceph_crypto_key_destroy(ac->session_key);
    ac->session_key = new_key;
    handler->start = start;
    handler->expiry = expiry;
    handler->ticket_blob = ticket_blob;
    handler->ticket_blob_len = (uintptr_t)end - (uintptr_t)ticket_blob;

out:
    // Clean up allocated resources
    if (decrypted_data) {
        free(decrypted_data);
    }
    return ret;
}
